def max_absolute_difference(n, a):
    max_diff = 0
    for k in range(1, n + 1):
        total_weight = sum(a)
        if total_weight % k == 0:
            trucks = [total_weight // k] * k
            for i in range(n):
                if i % k != 0:
                    trucks.append(total_weight // k)
            if len(trucks) == n:
                diff = max(trucks) - min(trucks)
                max_diff = max(max_diff, diff)
    return max_diff

