import sys
from collections import deque

def max_alternating_subarray_sum(n, arr):
    max_sum = float('-inf')
    dq = deque()
    for i in range(n):
        if dq and arr[i] == arr[dq[-1]]:
            dq.pop()
        else:
            dq.append(i)
        max_sum = max(max_sum, sum(arr[dq]))
    return max_sum

