def sum_of_power(nums):
    MOD = 10**9 + 7
    nums.sort()
    total_power = 0
    n = len(nums)

    for i in range(n):
        left = i
        right = i + 1
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < nums[i]:
                left = mid + 1
            else:
                right = mid

