def findLosers(n, k):
    losers = []
    visited = [False] * n

    def find_next_loser(i):
        if i == n - 1:
            return i

        next_loser = find_next_loser(i + k)
        if not visited[next_loser]:
            visited[next_loser] = True
            losers.append(next_loser)
            return next_loser
        else:
            return i

    for i in range(n):
        if not visited[i]:
            loser = find_next_loser(i)
            if loser != i:
                losers.append(loser)

    return sorted(losers)

