def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if math.gcd(nums[i], nums[j]) <= 1:
                return False
    return True

def smallestString(s: str) -> str:
    s = list(s)
    n = len(s)

    # Find the first character that is not 'z'
    for i in range(n):
        if s[i] != 'z':
            break

    # If all characters are 'z', return the string as is
    if i == n:
        return ''.join(s)

    # Find the last character that is not 'z'
    for i in range(n-1, -1, -1):
        if s[i] != 'z':
            break

    # Swap the first and last characters
    s[0], s[-1] = s[-1], s[0]

    # Reverse the substring from index 1 to n-1
    s[1:-1] = s[1:-1][::-1]

    return ''.join(s)

