def specialPerm(nums):
    MOD = 10**9 + 7
    def backtrack(i, path):
        if i == len(nums):
            return 1
        if i == len(nums):
            return 0
        if nums[i] % nums[i+1] == 0 or nums[i+1] % nums[i] == 0:
            return backtrack(i+1, path + [nums[i]])
        else:
            return 0

    return backtrack(0, [])

