def max_string_length(x, y, z):
    # Create a 3D array to store the maximum length of the string
    dp = [[[0 for _ in range(z + 1)] for _ in range(y + 1)] for _ in range(x + 1)]

    # Initialize the base case
    for i in range(x + 1):
        dp[i][0][0] = 1
        for j in range(y + 1):
            dp[i][j][0] = 1

    # Fill the dp table
    for i in range(x + 1):
        for j in range(y + 1):
            for k in range(z + 1):
                if i == 0:
                    dp[i][j][k] = 1
                elif j == 0:
                    dp[i][j][k] = 1
                elif k == 0:
                    dp[i][j][k] = 1
                elif x == 0:
                    dp[i][j][k] = 1
                elif y == 0:
                    dp[i][j][k] = 1
                elif z == 0:
                    dp[i][j][k] = 1
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1]) + 1

    return dp[x][y][z]

