def primePairs(n: int) -> list[list[int]]:
    prime_pairs = []
    for x in range(2, n+1):
        if n % x == 0:
            continue
        y = n // x
        if x > y:
            break
        if x == y:
            prime_pairs.append([x, x])
        else:
            if x < y:
                prime_pairs.append([x, y])
            else:
                prime_pairs.append([y, x])
    return sorted(prime_pairs)

