def minBeautifulSubstrings(s: str) -> int:
    if not s:
        return -1

    # Check if the string is a power of 5
    if s[0] == '0':
        return -1

    # Find the length of the binary representation of the number 5^k
    k = 0
    while (5 ** k) <= len(s):
        k += 1

    # Check if the binary representation of 5^k is a power of 5
    if s[0] != '1' and (s[0] == '1' and s[1] == '1' and s[2] == '1' and s[3] == '1'):
        return -1

    # Find the length of the binary representation of 5^k
    k = 0
    while (5 ** k) <= len(s):
        k += 1

    # Check if the binary representation of 5^k is a power of 5
    if s[0] != '1' and (s[0] == '1' and s[1] == '1' and s[2] == '1' and s[3] == '1'):
        return -1

    # Find the minimum number of substrings
    min_substrings = len(s)
    for i in range(1, len(s)):
        if s[i] != '1':
            min_substrings += 1
            if min_substrings > len(s) // 2:
                return -1

    return min_substrings

