def permuteVowels(s: str) -> str:
    vowels = 'aeiou'
    s = list(s)
    vowels_list = sorted(vowels)

    def permute(s, index, result):
        if index == len(s):
            return ''.join(result)

        for i in range(index, len(s)):
            if s[index] in vowels_list:
                result.append(s[index])
            else:
                result.append(s[index])

        return permute(s, index + 1, result)

    return permute(s, 0, [])

def find_dominant_split(nums):
    freq = {}
    dominant_element = None

    # Count the frequency of each element in the array
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

        # Check if the current element is dominant
        if freq[num] * 2 > len(nums):
            dominant_element = num
            break

    # If no dominant element is found, return -1
    if dominant_element is None:
        return -1

    # Find the minimum index of a valid split
    min_index = -1
    for i in range(len(nums) - 1):
        if nums[i] == dominant_element:
            min_index = i
            break

    return min_index

def maxBeauty(nums, k):
    nums.sort()
    left = 0
    right = len(nums) - 1
    max_beauty = 0

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] - nums[mid - 1] <= k:
            max_beauty = mid + 1
            left = mid + 1
        else:
            right = mid - 1

    return max_beauty

