from collections import deque

def can_complete_moves(N, M, H, K, S, x_list, y_list):
    # Initialize the BFS
    queue = deque([(0, 0, H)])
    visited = set((0, 0, H))

    while queue:
        x, y, health = queue.popleft()

        # Check all possible moves
        for move in ['R', 'L', 'U', 'D']:
            if move == 'R':
                new_x, new_y = x + 1, y
            elif move == 'L':
                new_x, new_y = x - 1, y
            elif move == 'U':
                new_x, new_y = x, y + 1
            elif move == 'D':
                new_x, new_y = x, y - 1

            # Check if the new position is valid
            if 0 <= new_x < N and 0 <= new_y < M:
                new_health = health - 1
                if new_health >= 0:
                    new_state = (new_x, new_y, new_health)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)

        # Check if Takahashi has collapsed
        if health < 0:
            return "Yes"

    return "No"

