def min_milliseconds(X, Y, Z, S):
    # Initialize the string and the total milliseconds
    string = ""
    total_milliseconds = 0

    # Iterate over the string S
    for char in S:
        if char == 'a':
            # Spend X milliseconds to press only the 'a' key
            total_milliseconds += X
            string += char
        elif char == 'a' and char != 'A':
            # Spend Y milliseconds to press the 'a' key and Shift key
            total_milliseconds += Y
            string += char
        elif char == 'A':
            # Spend Z milliseconds to press the Caps Lock key
            if not string:
                total_milliseconds += Z
                string = "a"
            else:
                total_milliseconds += Z
                string += "a"

    return total_milliseconds

