def find_cycle(N, A):
    visited = [False] * (N + 1)
    parent = [-1] * (N + 1)
    cycle = []

    def dfs(v):
        visited[v] = True
        for i in range(1, N + 1):
            if not visited[i] and A[i] == v:
                cycle.append(i)
                parent[i] = v
                dfs(i)
                if parent[v] == -1:
                    cycle.append(v)
                    break

    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i)

    return cycle

