def count_ice_squares(N, M, S):
    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1  # Starting point

    for i in range(N):
        for j in range(M):
            if S[i][j] == '.':
                dp[i][j] = dp[i-1][j] + dp[i][j-1] + dp[i-1][j-1]
            elif S[i][j] == '#':
                dp[i][j] = dp[i-1][j] + dp[i][j-1] + dp[i-1][j-1] - dp[i-1][j-1]  # Subtract the overlapping squares

    return dp[N-1][M-1]

