def count_holeless_squares(H, W, N, holed_squares):
    count = 0

    # Iterate over all possible top-left corners (i, j)
    for i in range(H):
        for j in range(W):
            # Iterate over all possible bottom-right corners (i + n - 1, j + n - 1)
            for n in range(1, N + 1):
                if i + n - 1 >= H or j + n - 1 >= W:
                    continue
                if (i, j) in holed_squares or (i + n - 1, j + n - 1) in holed_squares:
                    continue
                count += 1

    return count

