def is_valid_parenthesis(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def count_valid_parenthesis(s):
    q = s.count('?')
    total_combinations = 1
    for i in range(1 << q):
        s_i = list(s)
        for j in range(q):
            if i & (1 << j):
                s_i[j] = '('
        if is_valid_parenthesis(''.join(s_i)):
            total_combinations = (total_combinations * pow(2, q, MOD)) % MOD
    return total_combinations

