def max_weight_edges(N, edges):
    # Initialize dp array with -1
    dp = [[-1] * (N + 1) for _ in range(N + 1)]

    # Base case: if there is only one vertex, the maximum weight is the weight of that vertex
    for i in range(1, N + 1):
        dp[i][i] = edges[i - 1][i - 1]

    # Fill the dp array
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            for k in range(i + 1, j + 1):
                if dp[i][j] != -1:
                    dp[i][j] = max(dp[i][j], dp[i][j] + edges[k - 1][j - 1])

    # The answer is the maximum weight of edges we can select from the whole graph
    return dp[1][N]

