class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1

def determine_coordinates(N, M, pieces):
    uf = UnionFind(N)

    for A, B, X, Y in pieces:
        A -= 1
        B -= 1
        for i in range(N):
            if uf.find(A) == uf.find(B):
                uf.union(A, B)

    coordinates = []
    for i in range(N):
        root = uf.find(i)
        if uf.rank[root] == 1:
            coordinates.append((i, uf.find(i)))
        else:
            coordinates.append("undecidable")

    return coordinates

