def ctz(N):
    if N == 0:
        return 0

    binary_representation = bin(N)[2:]

    if binary_representation[-1] == '1':
        return 0

    count = 0
    while binary_representation[-1] == '0':
        binary_representation = '1' + binary_representation
        count += 1

    return count

