def min_moves_to_same_cell(grid, players):
    N = len(grid)

    # Find the positions of the two players
    player1_pos = None
    player2_pos = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                if player1_pos is None:
                    player1_pos = (i, j)
                elif player2_pos is None:
                    player2_pos = (i, j)

    # If there are not exactly two players, return -1
    if len(player1_pos) != 2 or len(player2_pos) != 2:
        return -1

    # BFS to find the shortest path between the two players
    queue = deque([(player1_pos[0], player1_pos[1], 0)])
    visited = set()
    visited.add(player1_pos)

    while queue:
        x, y, moves = queue.popleft()

        # Check all four directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy

            # Check if the new position is within bounds and not visited
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                if grid[nx][ny] == '.':
                    visited.add((nx, ny))
                    queue.append((nx, ny, moves + 1))
                elif grid[nx][ny] == '#':
                    return -1  # Obstacle found, return -1

    # If we reach here, the players are on the same cell
    return moves

