def is_perfect_square(n):
    root = int(math.isqrt(n))
    return n == root * root

def count_valid_pairs(N, A):
    # Dictionary to store the frequency of each prime factor
    prime_count = defaultdict(int)

    # Calculate the prime factors of each number
    for num in A:
        factors = defaultdict(int)
        for i in range(2, int(math.isqrt(num)) + 1):
            while num % i == 0:
                factors[i] += 1
                num //= i
        if num > 1:
            factors[num] += 1

        # Check if the combined prime factors form a perfect square
        for prime, count in factors.items():
            if count % 2 != 0:
                return 0

    # Calculate the number of valid pairs
    total_pairs = 0
    for i in range(N):
        for j in range(i + 1, N):
            if is_perfect_square(A[i] * A[j]):
                total_pairs += N - i - j + 1

    return total_pairs

