class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.map = {}

    def insert_after(self, x, y):
        node = Node(y)
        node.next = self.head
        node.prev = self.head
        self.head.prev = node
        self.head = node

        node = Node(x)
        node.next = self.tail
        node.prev = self.tail
        self.tail.next = node
        self.tail = node

        self.map[y] = node
        self.map[x] = node

    def remove(self, x):
        node = self.map[x]
        if node:
            self.map[x] = node.prev
            if node.prev:
                node.prev.next = node.next
            if node.next:
                node.next.prev = node.prev
            del self.map[x]
            self.map[x] = None

def process_queries(N, A, Q, queries):
