def min_good_sequences(L, R):
    memo = {}

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i > j:
            return float('inf')
        if i == j:
            return 1
        if L <= i and R >= j:
            return dp(i, j-1) + 1
        if L <= i and R < j:
            return dp(i, j-1) + 1
        if L < i and R > j:
            return dp(i-1, j) + 1
        if L > i and R < j:
            return dp(i-1, j) + 1
        if L < i and R > j:
            return dp(i-1, j-1) + 1
        if L > i and R > j:
            return dp(i-1, j-1) + 1
        return min(dp(i, j-1), dp(i-1, j))

    return dp(L, R)

