def is_winner(grid, turn):
    # Check if there are three consecutive cells of the same color
    for i in range(3):
        for j in range(3):
            if grid[i][j] == grid[i][j+1] == grid[i][j+2]:
                return True

    # Check if there are white cells left
    for i in range(3):
        for j in range(3):
            if grid[i][j] == 0:
                return True

    # If no white cells remain, return the winner based on the current player's score
    if not grid[0][0] or not grid[2][2]:
        return grid[0][0] if turn == 'Takahashi' else grid[2][2]

    # Recursive function to determine the winner for the next player
    def next_player(grid, turn):
        if all(cell != 0 for row in grid for cell in row):
            return grid[0][0] if turn == 'Takahashi' else grid[2][2]

        max_score = -float('inf')
        for i in range(3):
            for j in range(3):
                if grid[i][j] != 0:
                    score = grid[i][j]
                    grid[i][j] = 0
                    if turn == 'Takahashi':
                        score += next_player(grid, 'Aoki')
                    else:
                        score += next_player(grid, 'Takahashi')
                    grid[i][j] = score
                    max_score = max(max_score, score)

        return max_score

    return next_player(grid, turn)

