def find_bingo_turn(N, T, A):
    grid = [[0] * N for _ in range(N)]

    # Initialize the grid with zeros
    for i in range(N):
        for j in range(N):
            grid[i][j] = N * (i - 1) + j

    bingo_turn = -1

    # Simulate the turns
    for turn in range(1, T + 1):
        A_i = A[turn - 1]
        grid[A_i - 1][A_i - 1] = 1  # Mark the cell

        # Check for Bingo conditions
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 1:
                    break
            else:
                bingo_turn = turn
                break

        # Check for diagonal lines
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 1:
                    break
            else:
                bingo_turn = turn
                break

        # Check for row and column lines
        for i in range(N):
            if grid[i][0] == 1:
                bingo_turn = turn
                break
            if grid[0][i] == 1:
                bingo_turn = turn
                break

        for j in range(N):
            if grid[0][j] == 1:
                bingo_turn = turn
                break
            if grid[i][j] == 1:
                bingo_turn = turn
                break

    return bingo_turn

