            if nums[i] != nums[j]:
                count += 1
    return count

def min_max_distance(points):
    n = len(points)
    if n < 2:
        return 0

    # Calculate the maximum distance between any two points
    max_distance = 0
    for i in range(n):
        for j in range(i + 1, n):
            max_distance = max(max_distance, abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]))

    # Remove one point and calculate the new maximum distance
    for i in range(n):
        max_distance = max(max_distance, abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]))

    return max_distance

def longest_subarray(nums):
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            current_length += 1
            max_length = max(max_length, current_length)
        elif nums[i] < nums[i-1]:
            current_length = 1
            max_length = max(max_length, current_length)
        else:
            current_length = 0
            max_length = max(max_length, current_length)

    return max_length

def smallest_string(s, k):
    s = list(s)
    n = len(s)

    for i in range(n):
        for j in range(26):
            if (ord(s[i]) - ord('a') + j) % 26 == k:
                s[i] = chr(ord('a') + j)
                break

    return ''.join(s)

def min_operations(nums, k):
    nums.sort()
    median = nums[len(nums) // 2]
    operations = 0
    for num in nums:
        if num == median:
            continue
        else:
            operations += abs(num - median)
    return operations

def latestTime(s: str) -> str:
    h, m = map(int, s[2:4])
    if h == 0 and m == 0:
        return "00:00"
    elif h == 1 and m == 1:
        return "11:00"
    elif h == 2 and m == 0:
        return "20:00"
    elif h == 3 and m == 1:
        return "09:59"
    elif h == 4 and m == 0:
        return "19:59"
    else:
        return "00:00"

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def max_prime_distance(nums):
    prime_indices = [i for i, num in enumerate(nums) if is_prime(num)]
    return max(abs(prime_indices[i] - prime_indices[prime_indices.index(i)]) for i in prime_indices)

def kthSmallestCoins(coins, k):
    coins.sort()
    coins.sort(reverse=True)

    def getCoins(coins, k):
        coins.sort()
        coins.sort(reverse=True)

        res = []
        for i in range(k):
            res.append(coins[i])
        return res

    return getCoins(coins, k)

def encrypt(nums):
    def max_digit(num):
        return max(str(num))

    return sum(int(str(num)[i]) for i in range(len(num)))

def mark_and_sum(nums, queries):
    n = len(nums)
    answer = []

    for index_i, k_i in queries:
        marked = False
        marked_elements = []

        for i in range(n):
            if not marked:
                if i == index_i:
                    marked = True
                else:
                    if nums[i] != 1:
                        marked_elements.append(nums[i])
                        marked = True
                    else:
                        marked_elements.append(1)

        if not marked:
            answer.append(sum(marked_elements))
        else:
            answer.append(sum(marked_elements))

    return answer

def minValue(s: str) -> str:
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        if s[i - 1] == '?':
            dp[i] = min(dp[i - 1], dp[i - 2] + 1)
        else:
            dp[i] = min(dp[i - 1], dp[i - 2])

    return ''.join(s[i] for i in range(n) if s[i] != '?' and dp[i] == dp[i - 1])

def sumOfPower(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    power = 0

    # Generate all possible subsequences
    for i in range(1, 1 << n):
        subseq = []
        for j in range(n):
            if i & (1 << j):
                subseq.append(nums[j])

        if sum(subseq) == k:
            power += 1

    return power % MOD

def minLevelsToWin(possible):
    n = len(possible)
    dp = [[-1] * n for _ in range(n)]
    dp[0][0] = 0

    for i in range(1, n):
        for j in range(i):
            if possible[j] == 1:
                dp[i][j] = max(dp[i][j], dp[j][i-1] + 1)
            else:
                dp[i][j] = max(dp[i][j], dp[j][i-1] - 1)

    return dp[n-1][n-1]

def count_subarrays(nums):
    count = 0
    max_num = max(nums)
    for i in range(len(nums)):
        if nums[i] == max_num:
            count += 1
    return count

def minimum_possible_value(n, x):
    nums = [0] * n
    nums[0] = x
    for i in range(1, n):
        nums[i] = nums[i - 1] + 1
    return nums[n - 1]

def median_of_uniqueness(nums):
    n = len(nums)
    uniqueness = []
    for i in range(n):
        distinct = set()
        for j in range(i, n):
            distinct.add(nums[j])
            uniqueness.append(len(distinct))
    uniqueness.sort()
    if n % 2 == 0:
        return uniqueness[n//2]
    else:
        return uniqueness[n//2 - 1]

def is_valid_word(word):
    vowels = "aeiouAEIOU"
    if len(word) < 3 or not word.isalnum():
        return False
    for char in word:
        if not char.isalnum():
            return False
    for char in word:
        if char not in vowels:
            return False
    return True

def min_operations_to_k_periodic(word, k):
    n = len(word)
    if n % k != 0:
        return -1

    operations = 0
    i = 0
    while i < n:
        j = i % k
        if j == 0:
            operations += 1
            i += 1
        else:
            i += 1

    return operations

def minLength(s: str) -> int:
    from collections import Counter

    # Count the frequency of each character in the string
    freq = Counter(s)

    # The minimum possible length of the string t is the total length of the string divided by the frequency of each character
    return len(s) // len(freq)

def validate_2x2_square(grid):
    for i in range(2):
        for j in range(2):
            if grid[i][j] == grid[i][j+1] == grid[i+1][j] == grid[i+1][j+1]:
                return True
    return False

def count_right_triangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                count += 1
                if i > 0 and grid[i-1][j] == 1:
                    count += 1
                if j > 0 and grid[i][j-1] == 1:
                    count += 1
    return count

def numStableBinaryArrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1

    for i in range(1, zero + 1):
        for j in range(1, one + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if j < one:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    return dp[zero][one]

def permutation_difference(s: str, t: str) -> int:
    s_index = {c: i for i, c in enumerate(s)}
    t_index = {c: i for i, c in enumerate(t)}

    return sum(abs(s_index[c] - t_index[c]) for c in s)

def sum_of_digit_differences(nums):
    num_digits = len(str(max(nums)))
    total_sum = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            total_sum += sum(int(digit) - int(nums[i]) for digit in str(nums[j]))
    return total_sum

def countGoodPairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % (nums2[j] * k) == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    while word:
        c = word[0]
        count = 0
        while word and word[0] == c:
            count += 1
            word = word[1:]
        comp += str(count) + c
    return comp

def maxSubsequenceSum(nums, queries):
    MOD = 10**9 + 7

    def max_subsequence_sum(pos, x):
        if pos == 0:
            return x
        else:
            return max(max_subsequence_sum(pos - 1, x), max_subsequence_sum(pos - 2, x - nums[pos]))

    ans = 0
    for pos, x in queries:
        ans = (ans + max_subsequence_sum(pos, x)) % MOD

    return ans

def min_partitions(s):
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1

    min_partitions = len(s)
    for char in count:
        if count[char] > 1:
            min_partitions -= count[char]

    return min_partitions

def xor_of_duplicates(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    result = 0
    for num, cnt in count.items():
        if cnt == 2:
            result ^= num

    return result

def find_index(nums, queries, x):
    answer = [-1] * len(queries)
    for i, query in enumerate(queries):
        count = nums.count(query)
        if count >= query:
            answer[i] = count
        else:
            answer[i] = -1
    return answer
